// "02 Validar preparo" in the internal intake workflow (jbztWHxbY8Vnth3c).
// P2 calls it after an authenticated upload or a generation request. Four closed kinds:
// - prepare_dispatch: staging video -> high-quality working master (action prepare);
// - subtitle_dispatch: immutable SRT/VTT/ASS version -> validated timeline cues (action subtitle_evidence).
// - music_dispatch: mood + optional user prompt -> generated instrumental track stored with hash (action store_audio).
// - scene_direction_dispatch: scene materials -> labelled contact sheets (action scene_sheets) -> art director decides
//   only the automatic scene fields.
const x=$input.first()?.json??{};
const object=v=>v&&typeof v==='object'&&!Array.isArray(v);
const keys=v=>Object.keys(v).sort().join(',');
const sha=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
if(!object(x)||x.schema_version!=='1.0'||typeof x.operation_id!=='string'||!x.operation_id.trim()||x.operation_id.length>120)throw new Error('INVALID_PREPARE_DISPATCH: identidade');
if(!object(x.policy))throw new Error('INVALID_PREPARE_DISPATCH: policy confiável obrigatória');
if(x.kind==='prepare_dispatch'){
 if(keys(x)!=='kind,operation_id,policy,schema_version,source')throw new Error('INVALID_PREPARE_DISPATCH: campos');
 if(!object(x.source)||keys(x.source)!=='key'||typeof x.source.key!=='string'||!x.source.key.startsWith('video-editor/incoming/')||x.source.key.split('/').includes('..'))throw new Error('INVALID_PREPARE_DISPATCH: staging S3 obrigatório');
 // The working profile is fixed here so P2 cannot silently degrade the master used by every render.
 // threads:4 matches the 4-vCPU mia-videos workers; veryfast keeps CRF 20 quality (SSIM -0.001) at ~2x the speed of fast.
 const policy={...x.policy,threads:4,max_working_mb:256,working_crf:20,working_preset:'veryfast',working_audio_bitrate_kbps:160,retain_original:false,cleanup_staged_source:true,staging_prefix:'video-editor/incoming/'};
 return [{json:{operation_id:x.operation_id,action:'prepare',payload:{source:x.source},policy}}];
}
if(x.kind==='subtitle_dispatch'){
 if(keys(x)!=='kind,operation_id,policy,schema_version,subtitle')throw new Error('INVALID_PREPARE_DISPATCH: campos');
 const s=x.subtitle;
 if(!object(s)||keys(s)!=='asset_id,format,sha256,source,version')throw new Error('INVALID_SUBTITLE_DISPATCH: legenda versionada obrigatória');
 if(typeof s.asset_id!=='string'||!s.asset_id.trim()||s.asset_id.length>80||!Number.isInteger(s.version)||s.version<1||!['srt','vtt','ass'].includes(s.format)||!sha(s.sha256))throw new Error('INVALID_SUBTITLE_DISPATCH: identidade/hash/formato');
 if(!object(s.source)||keys(s.source)!=='key'||typeof s.source.key!=='string'||!s.source.key.trim()||s.source.key.startsWith('/')||s.source.key.split('/').includes('..'))throw new Error('INVALID_SUBTITLE_DISPATCH: chave S3 autorizada obrigatória');
 const payload={source:s.source,asset_id:s.asset_id,version:s.version,format:s.format,expected_source_sha256:s.sha256};
 return [{json:{operation_id:x.operation_id,action:'subtitle_evidence',payload,policy:x.policy}}];
}
if(x.kind==='music_dispatch'){
 if(keys(x)!=='kind,music,operation_id,policy,schema_version')throw new Error('INVALID_PREPARE_DISPATCH: campos');
 // Same table as catalogs/creative-capabilities.v1.json music_generation.mood_prompts (checked by check_repository).
 const MOODS={"warm": "Warm, gentle and welcoming mood; soft acoustic instruments; calm, steady tempo.", "inspiring": "Inspiring, hopeful and uplifting mood; gradual build; light piano and strings.", "light": "Light, relaxed and cheerful mood; simple melody; easy, friendly rhythm.", "energetic": "Energetic and confident mood; clear upbeat rhythm; modern, bright sound.", "sober": "Sober, serious and discreet mood; minimal arrangement; low, steady pads."};
 const m=x.music;
 if(!object(m)||Object.keys(m).some(k=>!['mood','prompt'].includes(k))||!Object.hasOwn(MOODS,m.mood??''))throw new Error('INVALID_MUSIC_DISPATCH: clima');
 if('prompt'in m&&(typeof m.prompt!=='string'||!m.prompt.trim()||m.prompt.length>300))throw new Error('INVALID_MUSIC_DISPATCH: preferência musical');
 // Deterministic prompt: instrumental only; the user's words are a preference, never instructions to vocalize.
 const generation_prompt='Create instrumental background music only. No vocals, no speech, no lyrics. '+MOODS[m.mood]+(m.prompt?' Musical preference: '+m.prompt.trim():'');
 return [{json:{operation_id:x.operation_id,action:'generate_music',music:{mood:m.mood,...(m.prompt?{prompt:m.prompt.trim()}:{})},generation_prompt,policy:x.policy}}];
}
if(x.kind==='scene_direction_dispatch'){
 if(keys(x)!=='ai,constraints,context,kind,materials,operation_id,policy,request_sha256,scenes,schema_version')throw new Error('INVALID_PREPARE_DISPATCH: campos');
 const bad=m=>{throw new Error('INVALID_SCENE_DIRECTION_DISPATCH: '+m);};
 if(!sha(x.request_sha256))bad('request_sha256');
 if(!object(x.ai)||keys(x.ai)!=='art_model'||typeof x.ai.art_model!=='string'||!x.ai.art_model.trim())bad('modelo do diretor de arte');
 const M=x.materials;
 if(!Array.isArray(M)||!M.length||M.length>30)bad('materiais');
 for(const [i,m]of M.entries())if(!object(m)||keys(m)!=='id,sha256,source,type,version'||m.id!=='m'+(i+1)||!['image','video'].includes(m.type)||!Number.isInteger(m.version)||m.version<1||!sha(m.sha256)||!object(m.source)||keys(m.source)!=='key'||typeof m.source.key!=='string'||!m.source.key.trim()||m.source.key.startsWith('/')||m.source.key.split('/').includes('..'))bad('material '+i);
 const S=x.scenes,ids=new Set();
 if(!Array.isArray(S)||!S.length||S.length>30)bad('cenas');
 for(const sc of S){
  if(!object(sc)||typeof sc.id!=='string'||!/^[a-zA-Z0-9][a-zA-Z0-9_-]{0,79}$/.test(sc.id)||ids.has(sc.id)||!M.some(m=>m.id===sc.material&&m.type===sc.kind))bad('cena');
  ids.add(sc.id);
 }
 const c=x.constraints;
 if(!object(c)||!['auto','manual'].includes(c.scene_order)||!object(c.automatic)||!Object.keys(c.automatic).length||!(c.target_content_seconds>0)||!(c.max_output_seconds>0)||!(c.min_scene_seconds>0)||!(c.max_scene_seconds>=c.min_scene_seconds)||!object(c.transition_rules)||!Array.isArray(c.transition_rules.types))bad('limites');
 if(!object(x.context))bad('contexto');
 return [{json:{operation_id:x.operation_id,action:'scene_sheets',payload:{sources:M},policy:x.policy,
  scene_request:{request_sha256:x.request_sha256,scenes:S,constraints:c,context:x.context,materials:M.map(({id,type})=>({id,type}))},ai:x.ai}}];
}
throw new Error('INVALID_PREPARE_DISPATCH: kind');

// "07 Validar estado" in the intake workflow. One poll every 5 s (node 05).
// 720 polls = 60 min, matching the engine's max_prepare_seconds; a 10-min 1080p source needs ~25 min
// on a 2-vCPU worker. Timeout never resubmits: P2 consults the same job URL.
const job=$input.first().json,ctx=$('04 Fixar UUID do job').first().json;
const completed=job.type==='CompletedJob'||job.completed_at!=null||typeof job.success==='boolean';
const attempt=$runIndex+1;
if(job.id!==ctx.windmill_job_id)throw new Error('WINDMILL_PREPARE_JOB_MISMATCH');
if(job.canceled||job.is_canceled||(completed&&job.success!==true))throw new Error('WINDMILL_PREPARE_FAILED: '+(job.result?.error?.message??'')+' '+ctx.windmill_job_url);
if(!completed&&attempt>=720)throw new Error('WINDMILL_PREPARE_TIMEOUT: não reenviar automaticamente; '+ctx.windmill_job_url);
return [{json:{...ctx,attempt,completed,result:completed?job.result:null}}];

// "09 Working pronta" in the internal intake workflow. Accepts only the result of the
// action that "02 Validar preparo" queued; never pins an exact engine release.
// The input is the full job result ("Ler resultado do job"): the job status endpoint omits large results.
const x=$('04 Fixar UUID do job').first().json,r=$input.first().json,request=$('02 Validar preparo').first().json;
const sha=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
const base={operation_id:x.operation_id,windmill_job_id:x.windmill_job_id,windmill_job_url:x.windmill_job_url};
if(!r||typeof r.engine_version!=='string'||!/^\d+\.\d+\.\d+$/.test(r.engine_version))throw new Error('WORKING_RESULT_INVALID: engine_version');
if(request.action==='prepare'){
 const p=r.working_profile,cleanup=r.source_cleanup?.status;
 if(!r.working_source?.key||!sha(r.working_sha256)||!sha(r.input_sha256)||p?.crf!==20||p?.preset!=='veryfast'||p?.audio_bitrate_kbps!==160||r.original_retained!==false)throw new Error('WORKING_RESULT_INVALID: perfil/hash');
 // "pending" keeps a valid working master; P2 must retry the staging cleanup without re-encoding.
 if(!['deleted','pending'].includes(cleanup))throw new Error('WORKING_RESULT_INVALID: limpeza do staging');
 if(typeof r.media?.has_audio!=='boolean'||!(r.media.duration_seconds>0))throw new Error('WORKING_RESULT_INVALID: media');
 return [{json:{status:'ready',kind:'working',...base,engine_version:r.engine_version,working_source:r.working_source,
  working_sha256:r.working_sha256,input_sha256:r.input_sha256,working_profile:p,media:r.media,input:r.input,
  source_cleanup:r.source_cleanup,warnings:cleanup==='pending'?['STAGING_CLEANUP_PENDING']:[]}}];
}
if(request.action==='subtitle_evidence'){
 const q=request.payload;
 if(r.kind!=='subtitle_evidence'||r.asset_id!==q.asset_id||r.version!==q.version||r.sha256!==q.expected_source_sha256||r.format!==q.format||r.timing_basis!=='timeline'||!sha(r.evidence_sha256)||!Array.isArray(r.segments)||!r.segments.length)throw new Error('SUBTITLE_RESULT_INVALID: evidência não corresponde à versão pedida');
 const {windmill_job_id,...subtitle_evidence}=r;
 return [{json:{status:'ready',kind:'subtitle_evidence',...base,engine_version:r.engine_version,subtitle_evidence}}];
}
if(request.action==='generate_music'){
 // Stored track ready to be registered by P2 as an immutable audio asset version (content_sha256 = sha256).
 const a=r.asset;
 if(a?.id!=='generated_music'||a.type!=='audio'||typeof a.source?.key!=='string'||!a.source.key||!sha(r.sha256)||!(r.size_bytes>0)||!(r.media?.duration_seconds>0)||r.media.has_audio!==true)throw new Error('MUSIC_RESULT_INVALID: trilha armazenada sem hash ou duração');
 return [{json:{status:'ready',kind:'generated_music',...base,engine_version:r.engine_version,audio_source:a.source,
  sha256:r.sha256,size_bytes:r.size_bytes,media:r.media,generation:{model:'google/lyria-3-clip-preview',...request.music}}}];
}
throw new Error('WORKING_RESULT_INVALID: action');

// "Ler trilha gerada" in the intake workflow: the provider's SSE stream -> one base64 audio for store_audio.
// Same parsing rules as "Ler musica gerada" in the editor workflow; the audio never goes to a document or log.
const raw=$input.first().json.data,request=$('02 Validar preparo').first().json;
if(typeof raw!=='string'||raw.length>30*1024*1024)throw new Error('MUSIC_GENERATION_FAILED: resposta ausente ou grande demais');
const chunks=[];let done=false;
for(const line of raw.split(/\r?\n/)){
 if(!line.startsWith('data:'))continue;
 const text=line.slice(5).trim();if(text==='[DONE]'){done=true;continue;}if(!text)continue;
 const event=JSON.parse(text);if(event.error)throw new Error('MUSIC_GENERATION_FAILED: provedor');
 const data=event.choices?.[0]?.delta?.audio?.data;
 if(data){if(typeof data!=='string'||!/^[A-Za-z0-9+/]*={0,2}$/.test(data))throw new Error('MUSIC_GENERATION_FAILED: chunk inválido');chunks.push(Buffer.from(data,'base64'));}
}
if(!done||!chunks.length)throw new Error('MUSIC_GENERATION_FAILED: geração incompleta ou sem áudio');
const audio=Buffer.concat(chunks);if(audio.length>20*1024*1024)throw new Error('AUDIO_TOO_LARGE: trilha excede o limite');
return [{json:{operation_id:request.operation_id,action:'store_audio',payload:{data:audio.toString('base64')},policy:request.policy}}];

// "Preparar direção de cenas" in the intake workflow: contact sheets from the engine -> the art director's request.
// The director sees up to six sheets; empty slots are a blank frame, never another material.
// The input is the full job result ("Ler resultado do job"); ids come from the job node.
const x=$('04 Fixar UUID do job').first().json,r=$input.first().json,request=$('02 Validar preparo').first().json,q=request.scene_request;
const BLANK='data:image/jpeg;base64,/9j/4AAQSkZJRgABAgAAAQABAAD//gAQTGF2YzYwLjMxLjEwMgD/2wBDAAgUFBcUFxsbGxsbGyAeICEhISAgICAhISEkJCQqKiokJCQhISQkKCgqKi4vLisrKisvLzIyMjw8OTlGRkhWVmf/xABLAAEBAAAAAAAAAAAAAAAAAAAACAEBAAAAAAAAAAAAAAAAAAAAABABAAAAAAAAAAAAAAAAAAAAABEBAAAAAAAAAAAAAAAAAAAAAP/AABEIABAAEAMBIgACEQADEQD/2gAMAwEAAhEDEQA/AJ/AB//Z';
if(!r||r.kind!=='scene_sheets'||!/^\d+\.\d+\.\d+$/.test(r.engine_version??'')||!Array.isArray(r.sheets)||!r.sheets.length||r.sheets.length>6)throw new Error('SCENE_SHEETS_INVALID: folhas de contato ausentes');
if(JSON.stringify((r.assets??[]).map(a=>[a.id,a.type]))!==JSON.stringify(q.materials.map(m=>[m.id,m.type])))throw new Error('SCENE_SHEETS_INVALID: materiais não correspondem ao pedido');
if(r.sheets.some(s=>typeof s.image_url!=='string'||!s.image_url.startsWith('data:image/jpeg;base64,')||!Array.isArray(s.tiles)))throw new Error('SCENE_SHEETS_INVALID: folha inválida');
const materials=r.assets.map(a=>({id:a.id,type:a.type,has_audio:a.has_audio,width:a.width,height:a.height,...(a.type==='video'?{duration_seconds:a.duration_seconds}:{})}));
const art_request={task:'scene_direction',context:q.context,constraints:q.constraints,scenes:q.scenes,materials,
 sheets:r.sheets.map((s,i)=>({image:i+1,tiles:s.tiles.map(t=>({material:t.asset_id,time:t.time}))})),empty_images:6-r.sheets.length};
const images=[...r.sheets.map(s=>s.image_url),...Array(6-r.sheets.length).fill(BLANK)];
return [{json:{art_request,images,operation_id:request.operation_id,windmill_job_id:x.windmill_job_id,windmill_job_url:x.windmill_job_url}}];

// "Validar direção de cenas": the director decides only the automatic fields, inside the limits it received.
// The backend applies the result again (apply_scene_direction) and recompiles every limit; this node fails early.
const prepared=$('Preparar direção de cenas').first().json,q=$('02 Validar preparo').first().json.scene_request,c=q.constraints;
const raw=$input.first().json,text=raw.output??raw.text??raw;
let d;try{d=typeof text==='string'?JSON.parse(text.replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,'')):text;}catch{throw new Error('SCENE_DIRECTION_INVALID: resposta não é JSON');}
const bad=m=>{throw new Error('SCENE_DIRECTION_INVALID: '+m);};
const obj=v=>v&&typeof v==='object'&&!Array.isArray(v),num=v=>typeof v==='number'&&Number.isFinite(v);
if(!obj(d)||Object.keys(d).sort().join(',')!=='decision_report,scene_order,scenes')bad('campos');
const byId=new Map(q.scenes.map(s=>[s.id,s])),order=d.scene_order;
if(!Array.isArray(order)||order.length!==q.scenes.length||new Set(order).size!==order.length||order.some(id=>!byId.has(id)))bad('a ordem precisa listar cada cena uma vez');
if(c.scene_order==='manual'&&JSON.stringify(order)!==JSON.stringify(q.scenes.map(s=>s.id)))bad('a ordem é do usuário');
const auto=c.automatic,field={duration:'duration_seconds',source_start:'source_start_seconds',transition_after:'transition'};
if(!Array.isArray(d.scenes))bad('cenas');
const decided=new Map();
for(const item of d.scenes){
 if(!obj(item)||!byId.has(item.id)||decided.has(item.id)||!auto[item.id])bad('decisão para cena sem campo automático');
 const expected=auto[item.id].map(f=>field[f]).sort().join(',');
 if(Object.keys(item).filter(k=>k!=='id').sort().join(',')!==expected)bad(item.id+': decida exatamente '+expected);
 decided.set(item.id,item);
}
const pending=Object.keys(auto).filter(id=>id!=='_order'&&!decided.has(id));
if(pending.length)bad('faltam decisões: '+pending.join(', '));
const value=(s,k,manual)=>{const it=decided.get(s.id);return it&&k in it?it[k]:manual;};
let total=0;
for(const [i,id]of order.entries()){
 const s=byId.get(id),dur=value(s,'duration_seconds',s.duration.seconds);
 if(!num(dur)||dur<c.min_scene_seconds||dur>c.max_scene_seconds)bad(id+': duração fora dos limites');
 if(s.kind==='video'&&!s.loop){const start=value(s,'source_start_seconds',s.source_start?.seconds);if(!num(start)||start<0||start+dur>s.material_seconds+1e-6)bad(id+': trecho passa do fim do vídeo');}
 const t=value(s,'transition',null);
 let overlap=0;
 if(t){
  if(!obj(t))bad(id+': transição');
  if(t.type==='cut'){if(Object.keys(t).length!==1)bad(id+': corte não tem duração');}
  else{
   const keys=['type','duration_seconds',...(['wipe','slide'].includes(t.type)?['direction']:[])].sort().join(',');
   if(!c.transition_rules.types.includes(t.type)||Object.keys(t).sort().join(',')!==keys||!num(t.duration_seconds)||t.duration_seconds<=0||t.duration_seconds>c.transition_rules.max_seconds||(t.direction!==undefined&&!['left','right','up','down'].includes(t.direction)))bad(id+': transição fora das regras');
   if(i===order.length-1)bad('a última cena termina em corte');
   overlap=t.duration_seconds;
  }
 }else if(s.transition_after.mode==='manual'&&s.transition_after.type!=='cut'){if(i===order.length-1)bad('a última cena termina em corte');overlap=s.transition_after.duration_seconds??0;}
 total+=dur-overlap;
}
if(total>c.max_output_seconds+1e-6)bad('sequência passa do máximo de '+c.max_output_seconds+'s');
const report=d.decision_report;
if(!obj(report)||typeof report.summary!=='string'||!report.summary.trim()||report.summary.length>1200||!Array.isArray(report.decisions)||report.decisions.length>40)bad('relatório de decisões');
return [{json:{status:'ready',kind:'scene_direction',operation_id:prepared.operation_id,windmill_job_id:prepared.windmill_job_id,windmill_job_url:prepared.windmill_job_url,
 content_seconds:Math.round(total*1000)/1000,direction:{kind:'scene_direction',request_sha256:q.request_sha256,scene_order:order,scenes:d.scenes,decision_report:report}}}];
